public class Main {
    static int 查了几项 = 0;
    static int 红了几项 = 0;

    static void 查相等(String 名字, int 叼回来, int 该是) {
        查了几项++;
        if (叼回来 == 该是) {
            System.out.println("绿 " + 名字);
        } else {
            红了几项++;
            System.out.println("红 " + 名字 + "：叼回来 " + 叼回来 + "，该是 " + 该是);
        }
    }

    static int 平分(int 总数, int 份数) {
        return 总数 / 份数;
    }

    public static void main(String[] args) {
        查相等("刚够分", 平分(6, 2), 3);
        查相等("一条都没有的时候", 平分(0, 3), 0);
        查相等("只有一份的时候", 平分(7, 1), 7);
        查相等("特别大的数", 平分(2147483647, 2), 1073741823);
        System.out.println("体检了 " + 查了几项 + " 项，红了 " + 红了几项 + " 项");
    }
}

